// Procedural station sounds, enabled by default and unlocked by the first browser gesture.
let audioContext,stationSound=true,soundLoop,stationNarrating=false;
function tone(freq,duration=.2,type='sine',volume=.05,delay=0){if(!stationSound||audioContext?.state!=='running')return;const a=audioContext,o=a.createOscillator(),g=a.createGain(),t=a.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(stationNarrating?volume*.15:volume,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.start(t);o.stop(t+duration+.02)}
function hiss(duration=.14,volume=.025){if(!stationSound||audioContext?.state!=='running')return;const a=audioContext,b=a.createBuffer(1,a.sampleRate*duration,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);const n=a.createBufferSource(),f=a.createBiquadFilter(),g=a.createGain();n.buffer=b;f.type='lowpass';f.frequency.value=1100;g.gain.value=stationNarrating?volume*.15:volume;n.connect(f);f.connect(g);g.connect(a.destination);n.start()}
function stationBell(){tone(784,.8,'sine',.055);tone(1046,.9,'sine',.035,.22)}
function whistle(){[523,659,784].forEach(f=>tone(f,1.15,'sine',.026));hiss(.9,.04)}
function boardClack(){tone(175,.035,'square',.009);tone(230,.03,'square',.008,.055)}
const soundButton=document.querySelector('#sound');
function updateSoundControl(){soundButton.textContent=stationSound?'Sound: on':'Sound: off';soundButton.setAttribute('aria-pressed',String(stationSound))}
function startAmbience(){clearInterval(soundLoop);if(!stationSound)return;soundLoop=setInterval(()=>{if(document.hidden)return;hiss(.15,.017);if(Math.random()>.85)tone(392,.25,'sine',.012)},600)}
async function unlockSound(){if(!stationSound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audioContext ||= new Audio();await audioContext.resume();if(stationSound){startAmbience();stationBell()}}catch{}}
function firstSoundGesture(event){if(event.target.closest?.('#sound')||!stationSound||audioContext?.state==='running')return;unlockSound()}
document.addEventListener('pointerdown',firstSoundGesture,{capture:true});document.addEventListener('keydown',firstSoundGesture,{capture:true});
soundButton.onclick=()=>{stationSound=!stationSound;updateSoundControl();clearInterval(soundLoop);if(stationSound)unlockSound()};updateSoundControl();
document.addEventListener('visibilitychange',()=>{if(audioContext){if(document.hidden)audioContext.suspend();else if(stationSound)audioContext.resume().catch(()=>{})}});
function trainArt(){return `<div class="train-art" aria-hidden="true"><div class="steam"><i></i><i></i><i></i></div><div class="engine"><div class="chimney"></div><div class="cab"><span>✦</span><div class="cab-window"></div></div><div class="boiler"><span>FALCON EXPRESS</span></div><div class="headlamp"></div><div class="cowcatcher"></div><div class="train-wheels"><i></i><i></i><i></i></div><div class="connecting-rod"></div></div>${[0,1].map(()=>`<div class="carriage"><span>THE FALCON WAY</span><div class="windows"><i></i><i></i><i></i></div><div class="carriage-wheels"><i></i><i></i></div></div>`).join('')}</div>`}
function stationPlatform(){return `<section class="station-platform" aria-label="The Falcon Express arriving at the station"><div class="station-roof"><span>✦ FALCON CENTRAL ✦</span></div><div class="station-sky"><div class="station-clock"><span class="hour-hand"></span><span class="minute-hand"></span><b>✦</b></div><div class="hanging-sign">THE FALCON EXPRESS<br><small>GOOD CHOICES · ALL DAY</small></div><div class="station-lights"><i></i><i></i><i></i></div></div><div class="platform-train">${trainArt()}</div><div class="rails"></div><div class="platform-edge"></div><div class="platform-bottom"><span class="arrival-dot"></span><span id="arrival-status">The Falcon Express is pulling in!</span><button id="call-train">Call the train</button></div></section>`}
function arrival(){const train=document.querySelector('.platform-train');if(!train)return;train.classList.remove('arriving');void train.offsetWidth;train.classList.add('arriving');whistle();const status=document.querySelector('#arrival-status');status.textContent='The Falcon Express is pulling in!';setTimeout(()=>{if(status.isConnected)status.textContent='All aboard! Choose a destination below.';stationBell()},reduced?0:4200)}
